function validate([lcp]) {
  const n = lcp.length;
  if (n < 1 || n > 1000) return 'lcp needs 1 to 1000 rows.';
  for (const row of lcp) {
    if (!Array.isArray(row) || row.length !== n) return 'lcp must be a square matrix.';
    for (const value of row) if (!Number.isInteger(value) || value < 0 || value > n) return 'Each entry is a whole number from 0 to n.';
  }
  return null;
}

