function findTheString(lcp) {
  const n = lcp.length;
  const word = [];
  // Compare two suffixes letter by letter.
  const common = (i, j) => {
    let length = 0;
    while (i + length < n && j + length < n && word[i + length] === word[j + length]) length++;
    return length;
  };
  // Try letters in order, using a new letter only right after the largest one used so far;
  // any valid string can be relabelled this way without getting larger.
  const search = (i, used) => {
    if (i === n) {
      for (let a = 0; a < n; a++) for (let b = 0; b < n; b++) if (common(a, b) !== lcp[a][b]) return null;
      return word.map(c => String.fromCharCode(97 + c)).join('');
    }
    for (let c = 0; c <= Math.min(used, 25); c++) {
      word[i] = c;
      let fits = true;
      for (let j = 0; j < i; j++) if ((word[j] === c) !== (lcp[j][i] > 0)) fits = false;
      if (!fits) continue;
      const found = search(i + 1, Math.max(used, c + 1));
      if (found !== null) return found;
    }
    return null;
  };
  return search(0, 0) ?? '';
}

