function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 7);
  const kinds = size === 'large' ? 1 + Math.floor(rand() * 30) : 1 + Math.floor(rand() * 4);
  const symbols = Array.from({ length: n }, () => Math.floor(rand() * kinds));
  // Build the true LCP matrix of a random string over `kinds` symbols (more than 26 means no answer).
  const lcp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (symbols[i] === symbols[j]) lcp[i][j] = 1 + (i + 1 < n && j + 1 < n ? lcp[i + 1][j + 1] : 0);
    }
  }
  const mode = rand();
  if (mode < 0.5) return [lcp];
  const i = Math.floor(rand() * n), j = Math.floor(rand() * n);
  const value = rand() < 0.5 ? Math.floor(rand() * (n + 1)) : Math.max(0, Math.min(n, lcp[i][j] + (rand() < 0.5 ? -1 : 1)));
  lcp[i][j] = value;
  if (mode < 0.8) lcp[j][i] = value;
  return [lcp];
}
